/**
 * Os elementos surgiram por acaso? — o átomo montado próton a próton.
 *
 * O puzzle é um botão de −/+ que anda pela tabela periódica, e o painel de cima
 * (no DOM) já mostra símbolo, massa e categoria. O que faltava é o átomo: as
 * camadas se enchendo na ordem, uma a uma, até fechar. É aí que "cada próton
 * muda tudo" deixa de ser uma frase — o desenho inteiro se reorganiza a cada
 * clique, e a camada de valência (a última, a que reage) fica em destaque.
 *
 * As camadas vêm de `info.camadas`, no formato `2,8,18,32,18,1` que a tabela do
 * módulo guarda. A cor do núcleo é a da categoria química, a mesma que o painel
 * usa: quem vê os dois juntos não precisa traduzir nada.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Acima disto o anel vira um colar sólido; o número diz o resto. */
const ELETRONS_DESENHADOS = 18;

const elementos: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const z = Math.max(1, Math.round(numeroDe(info, 'z', 1)));
    const simbolo = textoDe(info, 'simbolo') || '?';
    const catCor = textoDe(info, 'catCor') || '#6c757d';
    const ok = info.ok === true;
    const miudo = limitar(A * 0.03, 8, 11);

    const camadas = textoDe(info, 'camadas')
      .split(',')
      .map((n) => Number.parseInt(n.trim(), 10))
      .filter((n) => Number.isFinite(n) && n > 0);

    titulo(ctx, L, A, 'Cada próton a mais é outro elemento');

    const cx = L * 0.5;
    const cy = A * 0.54;
    const raioMax = Math.min(L * 0.42, A * 0.36);

    // ── O núcleo ──────────────────────────────────────────────────────────
    const raioNucleo = limitar(raioMax * 0.16, 12, 34);
    const halo = ctx.createRadialGradient(cx, cy, 0, cx, cy, raioNucleo * 1.9);
    halo.addColorStop(0, `${catCor}55`);
    halo.addColorStop(1, `${catCor}00`);
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(cx, cy, raioNucleo * 1.9, 0, Math.PI * 2);
    ctx.fill();

    disco(ctx, cx, cy, raioNucleo, catCor);
    ctx.strokeStyle = ok ? cor.verde : cor.texto;
    ctx.lineWidth = ok ? 3 : 1.6;
    ctx.beginPath();
    ctx.arc(cx, cy, raioNucleo, 0, Math.PI * 2);
    ctx.stroke();

    texto(ctx, simbolo, cx, cy - raioNucleo * 0.12, raioNucleo * 0.72, {
      cor: cor.contraste,
      peso: 800,
    });
    texto(ctx, `${z}p`, cx, cy + raioNucleo * 0.52, raioNucleo * 0.36, {
      cor: cor.contraste,
      peso: 700,
    });

    // ── As camadas ────────────────────────────────────────────────────────
    const primeiro = raioNucleo * 1.9;
    const passo = camadas.length === 0 ? 0 : (raioMax - primeiro) / Math.max(1, camadas.length);

    for (const [nivel, eletrons] of camadas.entries()) {
      const raio = primeiro + passo * (nivel + 1);
      const valencia = nivel === camadas.length - 1;

      ctx.strokeStyle = valencia ? (ok ? cor.verde : cor.azul) : cor.trilho;
      ctx.lineWidth = valencia ? 2 : 1;
      ctx.beginPath();
      // Achatado: as camadas nascem umas dentro das outras, e círculos
      // concêntricos perfeitos leem como alvo de tiro, não como átomo.
      ctx.ellipse(cx, cy, raio, raio * 0.66, 0, 0, Math.PI * 2);
      ctx.stroke();

      // Camada de dentro gira mais rápido — é o que dá profundidade ao conjunto.
      const giro = t * (0.9 - nivel * 0.12);
      const quantos = Math.min(eletrons, ELETRONS_DESENHADOS);

      for (let i = 0; i < quantos; i++) {
        const ang = giro + (i / quantos) * Math.PI * 2;
        disco(
          ctx,
          cx + Math.cos(ang) * raio,
          cy + Math.sin(ang) * raio * 0.66,
          Math.max(2.4, raioNucleo * 0.16),
          valencia ? (ok ? cor.verde : cor.azul) : cor.fraco,
        );
      }

      // Cada contagem sai num ângulo próprio, varrendo do alto à direita: as
      // camadas estão a poucos pixels umas das outras, e alinhá-las na mesma
      // direção fazia os seis números do ouro virarem "2818321 8 1".
      const passeio = -Math.PI * 0.62 + (nivel / Math.max(1, camadas.length - 1)) * Math.PI * 0.85;
      texto(
        ctx,
        `${eletrons}`,
        cx + Math.cos(passeio) * (raio + miudo * 1.2),
        cy + Math.sin(passeio) * (raio * 0.66 + miudo * 1.2),
        miudo * 0.95,
        { cor: valencia ? cor.azul : cor.fraco, peso: valencia ? 800 : 600 },
      );
    }

    if (camadas.length > 0) {
      texto(ctx, 'camada de valência', cx, cy + raioMax * 0.78 + miudo * 1.4, miudo * 0.9, {
        cor: cor.azul,
        peso: 600,
      });
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      `${z} prótons: ${simbolo} — a ordem 1→92 não tem lacunas ✔`,
      'Some ou tire prótons e veja o átomo inteiro se refazer.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default elementos;
